(() => {
  "use strict";

  const state = {
    distance: 18.6,
    totalDistance: 3000,
    stampDistance: 50,
    currentPlace: "La Storta",
    nextPlace: "Isola Farnese"
  };
  const stageImage = "data:image/webp;base64,";

  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
  const formatKm = (value) => value.toLocaleString("fr-FR", {
    minimumFractionDigits: Number.isInteger(value) ? 0 : 1,
    maximumFractionDigits: 1
  });

  const toast = $("[data-toast]");
  let toastTimer;

  function showToast(message) {
    if (!toast) return;
    toast.textContent = message;
    toast.classList.add("is-visible");
    window.clearTimeout(toastTimer);
    toastTimer = window.setTimeout(() => toast.classList.remove("is-visible"), 3200);
  }

  function openModal(modal) {
    if (!modal) return;
    if (typeof modal.showModal === "function") {
      modal.showModal();
    } else {
      modal.setAttribute("open", "");
    }
    document.body.style.overflow = "hidden";
  }

  function closeModal(modal) {
    if (!modal) return;
    if (typeof modal.close === "function") {
      modal.close();
    } else {
      modal.removeAttribute("open");
    }
    document.body.style.overflow = "";
  }

  function buildPassport() {
    const grid = $("[data-stamp-grid]");
    if (!grid) return;

    const totalStamps = Math.ceil(state.totalDistance / state.stampDistance);
    const completedStamps = Math.floor(state.distance / state.stampDistance);
    const fragment = document.createDocumentFragment();

    for (let index = 1; index <= totalStamps; index += 1) {
      const slot = document.createElement("span");
      const threshold = index * state.stampDistance;
      slot.className = "stamp-slot";
      slot.textContent = threshold;
      slot.title = `Tampon ${index} — ${formatKm(threshold)} km`;

      if (index <= completedStamps) {
        slot.classList.add("is-complete");
        slot.textContent = "✓";
      } else if (index === completedStamps + 1) {
        slot.classList.add("in-progress");
        slot.title = `Prochain tampon — ${formatKm(state.distance)} / ${formatKm(threshold)} km`;
      }

      fragment.appendChild(slot);
    }

    grid.replaceChildren(fragment);
  }

  function setActiveNav(target) {
    $$(".nav-link").forEach((link) => link.classList.remove("is-active"));
    const active = $(`[data-nav="${target}"]`);
    active?.classList.add("is-active");
  }

  $$("[data-distance]").forEach((element) => {
    element.textContent = formatKm(state.distance);
  });
  $$("[data-stage-image]").forEach((image) => {
    image.src = stageImage;
  });

  buildPassport();

  $$("[data-open-stage]").forEach((button) => {
    button.addEventListener("click", () => openModal($("[data-stage-modal]")));
  });

  $$("[data-open-passport]").forEach((button) => {
    button.addEventListener("click", () => openModal($("[data-passport-modal]")));
  });

  $$("[data-close-modal]").forEach((button) => {
    button.addEventListener("click", () => closeModal(button.closest("dialog")));
  });

  $$("dialog").forEach((dialog) => {
    dialog.addEventListener("click", (event) => {
      const bounds = dialog.getBoundingClientRect();
      const outside = (
        event.clientX < bounds.left ||
        event.clientX > bounds.right ||
        event.clientY < bounds.top ||
        event.clientY > bounds.bottom
      );
      if (outside) closeModal(dialog);
    });

    dialog.addEventListener("close", () => {
      document.body.style.overflow = "";
    });
  });

  $$("[data-coming-soon]").forEach((button) => {
    button.addEventListener("click", () => {
      const section = button.dataset.comingSoon;
      showToast(`${section} : la page détaillée arrive dans la prochaine étape du Camino Virtuel.`);
    });
  });

  $$("[data-nav]").forEach((link) => {
    link.addEventListener("click", () => setActiveNav(link.dataset.nav));
  });

  const observedSections = ["dashboard", "chemin", "carte"]
    .map((id) => document.getElementById(id))
    .filter(Boolean);

  if ("IntersectionObserver" in window) {
    const observer = new IntersectionObserver((entries) => {
      const visible = entries
        .filter((entry) => entry.isIntersecting)
        .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
      if (visible?.target?.id) setActiveNav(visible.target.id);
    }, { rootMargin: "-20% 0px -65%", threshold: [0.05, 0.3, 0.6] });

    observedSections.forEach((section) => observer.observe(section));
  }
})();
